draw:
var omega = Math.sqrt(p.k / p.mass);
var T = 2 * Math.PI / omega;
var A = p.amplitude;
var eqX = W * 0.46, wallX = W * 0.06, scale = W * 0.26, midY = H * 0.24;
var x = A * Math.cos(omega * t);
var v = -A * omega * Math.sin(omega * t);
var massX = eqX + x * scale;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

ctx.fillStyle = C.faint;
ctx.fillRect(wallX - 8, midY - 40, 8, 80);

ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(wallX, midY);
var i, sx, sy;
for (i = 1; i <= 14; i++) {
  sx = wallX + (massX - 15 - wallX) * i / 14;
  sy = midY + (i % 2 === 0 ? -9 : 9) * (i === 14 ? 0 : 1);
  ctx.lineTo(sx, sy);
}
ctx.lineTo(massX - 15, midY);
ctx.stroke();

ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(eqX, midY - 46); ctx.lineTo(eqX, midY + 34); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("x = 0", eqX - 14, midY + 48);

ctx.fillStyle = C.figure;
ctx.fillRect(massX - 15, midY - 15, 30, 30);

ctx.strokeStyle = C.accent;
ctx.fillStyle = C.accent;
var ax = -omega * omega * x * scale * 0.06;
if (Math.abs(ax) > 3) {
  var dir = ax > 0 ? 1 : -1;
  var tipX = massX + ax;
  ctx.beginPath();
  ctx.moveTo(massX, midY - 26);
  ctx.lineTo(tipX, midY - 26);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(tipX, midY - 26);
  ctx.lineTo(tipX - 6 * dir, midY - 30);
  ctx.lineTo(tipX - 6 * dir, midY - 22);
  ctx.closePath(); ctx.fill();
  ctx.fillText("a", (massX + tipX) / 2 - 3, midY - 32);
}

var gy = H * 0.74, gh = H * 0.20;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(40, gy); ctx.lineTo(W - 12, gy); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("time", W - 42, gy + 16);
ctx.fillStyle = C.figure;
ctx.fillText("x", 20, gy - gh + 4);
ctx.fillStyle = C.accent;
ctx.fillText("v", 20, gy + 14);

var span = 2.4;
var n = 160;
ctx.lineWidth = 1.6;
ctx.strokeStyle = C.figure;
ctx.beginPath();
for (i = 0; i < n; i++) {
  var tt = t - span * (n - 1 - i) / (n - 1);
  var px = 40 + (W - 52) * i / (n - 1);
  var py = gy - Math.cos(omega * tt) * gh;
  if (i === 0) { ctx.moveTo(px, py); } else { ctx.lineTo(px, py); }
}
ctx.stroke();
ctx.strokeStyle = C.accent;
ctx.beginPath();
for (i = 0; i < n; i++) {
  var tt2 = t - span * (n - 1 - i) / (n - 1);
  var px2 = 40 + (W - 52) * i / (n - 1);
  var py2 = gy + Math.sin(omega * tt2) * gh * 0.7;
  if (i === 0) { ctx.moveTo(px2, py2); } else { ctx.lineTo(px2, py2); }
}
ctx.stroke();

out.note = "omega = " + omega.toFixed(2) + " rad/s, T = " + T.toFixed(3) + " s, f = " + (1 / T).toFixed(2) + " Hz, vmax = " + (A * omega).toFixed(2) + " m/s, amax = " + (A * omega * omega).toFixed(1) + " m/s^2";
